mapper.update:
update dishes
type_id = #{typeId}, name = #{name}, price = #{price}, image = #{image}, del_flag = #{delFlag}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select *
from dishes
where type_id = #{typeId}
  and name = #{name}
  and del_flag = 0
